import { useCallback, useMemo, useRef } from "react";
import { View } from "react-native";
import { useTheme } from "react-native-paper";
import {
  assignWizardsToRule,
  estimateIntervalBetweenCastsForRule,
  estimateManaConsumptionPerSecPerRule,
  getAutocastRuleBySpell,
  getAutocastStatusByRule,
  getCurrentAutocastStrategy,
  getFreeWizards,
  toggleAutocastRuleDisabled,
} from "../../backend/autocast/Autocast";
import { TransmutationSpell } from "../../backend/items/transmute/TransmutationSpell";
import { getResourceCap, Resource } from "../../backend/Resources";
import { Spells } from "../../backend/spells/Spells";
import { formatNumber } from "../../utils/FormattingUtils";
import { t } from "../../utils/I18n";
import { Markdown } from "./Markdown";
import { PlusMinusAllocator } from "./PlusMinusAllocator";
import Styles from "./Styles";
import { Text } from "./Text";
import { useGameState } from "./useGameState";

export function SpellWizardsInfo(props: { spellId: string }) {
  const state = useGameState();
  const stateRef = useRef(state);
  stateRef.current = state;

  const theme = useTheme();

  const spell = Spells.getById(props.spellId);
  const rule = getAutocastRuleBySpell(state, spell);

  const ruleStatus = getAutocastStatusByRule(state, rule);
  const isTransmutationSpell = spell instanceof TransmutationSpell;
  const craftAtOnceQuantity = rule?.extra?.quantity ?? 1;
  const showQuantity = isTransmutationSpell && ruleStatus.wizardsAssigned > 0;

  const intervalBetweenCasts = estimateIntervalBetweenCastsForRule(
    state,
    rule,
    ruleStatus,
  );
  const manaCostPerSec = estimateManaConsumptionPerSecPerRule(
    state,
    rule,
    ruleStatus,
  );

  const helperText = useMemo(
    () =>
      ruleStatus.wizardsAssigned > 0 && !ruleStatus.disabled
        ? t(`*({{secs}}s/cast; {{mana}}:mana:/s)*`, {
            secs: formatNumber(intervalBetweenCasts, { showDecimals: true }),
            mana: formatNumber(manaCostPerSec, { showDecimals: true }),
          })
        : ruleStatus.disabled
        ? t("(Disabled)")
        : "",
    [
      intervalBetweenCasts,
      ruleStatus.wizardsAssigned,
      ruleStatus.disabled,
      manaCostPerSec,
    ],
  );

  const wizardsAssignedComponent = useMemo(
    () => (
      <Markdown>
        {t("Assign wizards {{helperText}}", {
          helperText,
        })}
      </Markdown>
    ),
    [helperText],
  );

  const onPressPlus = useCallback(
    () =>
      stateRef.current.apply((state) => {
        const rule = getAutocastRuleBySpell(state, spell);
        if (rule == null) {
          // We must create a rule
          const currentStrategy = getCurrentAutocastStrategy(state);
          const newRule = {
            id: Math.random().toString(),
            disabled: false,
            wizardsAssigned: 0,
            spellId: props.spellId,
            conditions: [],
            extra: {},
          };
          currentStrategy.rules.push(newRule);
          state.global.autocast.currentStrategy = currentStrategy;
          state = assignWizardsToRule(state, newRule, 1);
        } else {
          state = assignWizardsToRule(state, rule, 1);
          if (rule.disabled) {
            state = toggleAutocastRuleDisabled(state, rule);
          }
        }
        return state;
      }),
    [props.spellId],
  );
  const onPressMinus = useCallback(() => {
    stateRef.current.apply((state) => {
      const rule = getAutocastRuleBySpell(state, spell);
      if (rule == null) {
        return state;
      }
      state = assignWizardsToRule(state, rule, -1);
      if (rule.disabled) {
        state = toggleAutocastRuleDisabled(state, rule);
      }
      if (getAutocastStatusByRule(state, rule).wizardsAssigned <= 0) {
        const currentStrategy = getCurrentAutocastStrategy(state);
        currentStrategy.rules = currentStrategy.rules.filter(
          (strategyRule) => rule != strategyRule,
        );
      }
      return state;
    });
  }, [props.spellId]);

  const allocator = useMemo(
    () => (
      <View style={[Styles.flexRowAlignCenter, Styles.ml8]}>
        <View style={Styles.mr4}>
          <Text>{ruleStatus.wizardsAssigned}</Text>
        </View>
        <PlusMinusAllocator
          disableMinus={ruleStatus.wizardsAssigned <= 0}
          disablePlus={getFreeWizards(state) <= 0}
          onPressPlus={onPressPlus}
          onPressMinus={onPressMinus}
        />
      </View>
    ),
    [
      ruleStatus.wizardsAssigned,
      getFreeWizards(state),
      onPressPlus,
      onPressMinus,
    ],
  );

  const quantityText = useMemo(
    () => <Markdown>{t("Amount to transmute")}</Markdown>,
    [],
  );
  const onPressPlusQuantity = useCallback(
    () =>
      stateRef.current.apply((state) => {
        const rule = getAutocastRuleBySpell(state, spell);
        if (rule == null) {
          // Do nothing
        } else {
          const quantity = rule.extra?.quantity ?? 1;
          const toIncreaseBy = Math.min(
            999 - quantity,
            Math.max(1, Math.ceil(quantity * 0.1)),
          );
          if (rule.extra == null) {
            rule.extra = {};
          }
          rule.extra.quantity = quantity + toIncreaseBy;
        }
        return state;
      }),
    [props.spellId],
  );
  const onPressMinusQuantity = useCallback(
    () =>
      stateRef.current.apply((state) => {
        const rule = getAutocastRuleBySpell(state, spell);
        if (rule == null) {
          // Do nothing
        } else {
          const quantity = rule.extra?.quantity ?? 1;
          const toDecreaseBy = Math.max(1, Math.ceil(quantity * 0.1));
          if (rule.extra == null) {
            rule.extra = {};
          }
          if (quantity - toDecreaseBy < 1) {
            return state;
          }
          rule.extra.quantity = quantity - toDecreaseBy;
        }
        return state;
      }),
    [props.spellId],
  );
  const manaCost = useMemo(() => {
    const manaCost = spell.getCost(state).resources[Resource.Mana] ?? 0;
    return manaCost * craftAtOnceQuantity;
  }, [craftAtOnceQuantity]);
  const manaCostOnIncrease = useMemo(() => {
    const craftAtOnceNewQuantity =
      craftAtOnceQuantity +
      Math.min(
        999 - craftAtOnceQuantity,
        Math.max(1, Math.ceil(craftAtOnceQuantity * 0.1)),
      );
    const manaCost = spell.getCost(state).resources[Resource.Mana] ?? 0;
    return manaCost * craftAtOnceNewQuantity;
  }, [craftAtOnceQuantity]);
  const maxMana = getResourceCap(state, Resource.Mana);
  const quantityAllocator = useMemo(
    () => (
      <View style={[Styles.flexRowAlignCenter, Styles.ml8]}>
        <View style={Styles.mr4}>
          <Text style={manaCost > maxMana && { color: theme.colors.error }}>
            {formatNumber(craftAtOnceQuantity)}
          </Text>
        </View>
        <PlusMinusAllocator
          disableMinus={craftAtOnceQuantity <= 1}
          disablePlus={
            manaCostOnIncrease > maxMana || craftAtOnceQuantity >= 999
          }
          onPressPlus={onPressPlusQuantity}
          onPressMinus={onPressMinusQuantity}
        />
      </View>
    ),
    [
      craftAtOnceQuantity,
      manaCostOnIncrease,
      maxMana,
      onPressPlus,
      onPressMinus,
    ],
  );

  return (
    <View>
      <View style={Styles.flexRowSpaceBetween}>
        <View style={Styles.flex}>{wizardsAssignedComponent}</View>
        {allocator}
      </View>
      {showQuantity && (
        <View style={[Styles.flexRowSpaceBetween, Styles.mt4]}>
          <View style={Styles.flex}>{quantityText}</View>
          {quantityAllocator}
        </View>
      )}
    </View>
  );
}
